import type { Row } from 'react-table';

export function getBatchSelectRange(
  rows: Row[],
  selectedRowIds: Record<string, boolean>,
  selectRange?: readonly [number, number],
  unselectRange?: readonly [number, number],
): Record<string, boolean> {
  // Here we calculate if we have to unselect when a reselection happens between the starting row
  // and the ending row if the ending row comes before the starting row. The same calculation is done
  // if the ending row comes after the starting row
  if (unselectRange) {
    const [unselectStart, unselectEnd] = unselectRange;

    if (!selectRange) {
      for (let index = unselectStart; index <= unselectEnd; index++) {
        const row = rows[index];
        selectedRowIds[row.id] = false;
      }
    } else {
      const [selectStart, selectEnd] = selectRange || [0, 0];

      const startDiff = unselectStart - selectStart;
      const endDiff = unselectEnd - selectEnd;

      if (startDiff < 0) {
        for (let index = unselectStart; index <= selectStart; index++) {
          const row = rows[index];
          selectedRowIds[row.id] = false;
        }
      }

      if (endDiff > 0) {
        for (let index = selectEnd; index <= unselectEnd; index++) {
          const row = rows[index];
          selectedRowIds[row.id] = false;
        }
      }
    }
  }

  if (selectRange) {
    const [selectStart, selectEnd] = selectRange;
    for (let index = selectStart; index <= selectEnd; index++) {
      const row = rows[index];
      selectedRowIds[row.id] = true;
    }
  }

  return { ...selectedRowIds } as Record<string, boolean>;
}
